param([Parameter(Mandatory=$true)][string]$SourcePath)
$ErrorActionPreference='Stop'
$projectRoot=Split-Path -Parent $PSScriptRoot
$source=(Resolve-Path -LiteralPath $SourcePath).Path
$destination=Join-Path $projectRoot 'src/main/resources/assets/guerra_ezuberante/textures/gui/title/guerra_ezuberante_menu_bg.png'
New-Item -ItemType Directory -Force -Path (Split-Path -Parent $destination) | Out-Null
$ffmpeg=Join-Path $projectRoot '.tools/ffmpeg/ffmpeg-9.0.2-essentials_build/bin/ffmpeg.exe'
# Mechanical size/color normalization only; the illustration itself is generated by imagegen.
& $ffmpeg -hide_banner -loglevel error -y -i $source -vf 'scale=1920:1080:force_original_aspect_ratio=increase:flags=lanczos,crop=1920:1080,format=rgb24' -frames:v 1 $destination
if($LASTEXITCODE -ne 0){throw 'Menu PNG normalization failed.'}
Write-Host "Saved opaque 1920x1080 menu artwork: $destination"
